import { db } from "./db";
import { users } from "./schema";
import bcrypt from "bcrypt";
import { eq } from "drizzle-orm";
import dotenv from "dotenv";
import { BACKEND_ECTD_TREE_SEED } from "./ctdTreeSeed";

dotenv.config();

async function seedUser() {
  const email = "testuser@gmail.com";
  const rawPassword = "testpass@2244";
  const role = "user";
  const name = "Test User";

  try {
    console.log(`Hashing password for ${email}...`);
    const hashedPassword = await bcrypt.hash(rawPassword, 10);

    // Check if user already exists
    const [existingUser] = await db
      .select()
      .from(users)
      .where(eq(users.email, email))
      .limit(1);

    if (existingUser) {
      console.log(`User ${email} already exists (ID: ${existingUser.id}). Updating user record...`);
      const [updated] = await db
        .update(users)
        .set({
          password: hashedPassword,
          role: role as "user" | "admin" | "superadmin",
          name: existingUser.name || name,
          updatedAt: new Date(),
        })
        .where(eq(users.email, email))
        .returning();

      console.log("✅ User updated successfully:", {
        id: updated.id,
        email: updated.email,
        role: updated.role,
        name: updated.name,
      });
    } else {
      console.log(`Inserting new user ${email}...`);
      const [inserted] = await db
        .insert(users)
        .values({
          email,
          password: hashedPassword,
          role: role as "user" | "admin" | "superadmin",
          name,
        })
        .returning();

      console.log("✅ User inserted successfully:", {
        id: inserted.id,
        email: inserted.email,
        role: inserted.role,
        name: inserted.name,
      });
    }

    console.log(`✅ Loaded ${BACKEND_ECTD_TREE_SEED.length} top-level eCTD modules into backend seed taxonomy.`);
    process.exit(0);
  } catch (error: any) {
    console.error("❌ Error seeding user:", error);
    process.exit(1);
  }
}

seedUser();

